	}
	return err
}

func (client *Client) FetchIssues(latest time.Time, c chan *github.Issue) {
	opt := &github.IssueListByRepoOptions{Since: latest, Sort: "updated", State: "all", Direction: "asc"}

	githubClient, err := client.getGitHubClient()
	if err != nil {
		close(c)
		glog.Error(err)
		return
	}

	count := 0
	for {
		client.limitsCheckAndWait()

		issues, resp, err := githubClient.Issues.ListByRepo(
			context.Background(),
			client.Org,
			client.Project,
			opt,
		)
		if err != nil {
			close(c)
			glog.Error(err)
			return
		}

		for _, issue := range issues {
			c <- issue
			count++
		}

		if resp.NextPage == 0 {
			break
		}
		opt.ListOptions.Page = resp.NextPage
	}

	glog.Infof("Fetched %d issues updated issue since %v.", count, latest)
	close(c)
}

func (l *HTTPTemplateFetcher) FetchTemplate(path string) (TemplateSource, error) {
	u, err := url.Parse(path)

	if err != nil {
		return nil, fmt.Errorf("error parsing given path as url: %s", err)
	}

	if u.IsAbs() {
		return nil, ErrAbsolutePathNotAllowed
	}

	// XXX Consider caching!
	for _, base := range l.URLs {
		u := base + "/" + path
		res, err := http.Get(u)
		if err != nil {
			continue
		}

		return NewHTTPSource(res)
	}
	return nil, ErrTemplateNotFound
}

