protected void scanJarFile(final File file) {
		final ZipFile zipFile;
		try {
			zipFile = new ZipFile(file);
		} catch (IOException ioex) {
			if (!ignoreException) {
				throw new FindFileException("Invalid zip: " + file.getName(), ioex);
			}
			return;
		}
		final Enumeration entries = zipFile.entries();
		while (entries.hasMoreElements()) {
			final ZipEntry zipEntry = (ZipEntry) entries.nextElement();
			final String zipEntryName = zipEntry.getName();
			try {
				if (StringUtil.endsWithIgnoreCase(zipEntryName, CLASS_FILE_EXT)) {
					final String entryName = prepareEntryName(zipEntryName, true);
					final ClassPathEntry classPathEntry = new ClassPathEntry(entryName, zipFile, zipEntry);
					try {
						scanEntry(classPathEntry);
					} finally {
						classPathEntry.closeInputStream();
					}
				} else if (includeResources) {
					final String entryName = prepareEntryName(zipEntryName, false);
					final ClassPathEntry classPathEntry = new ClassPathEntry(entryName, zipFile, zipEntry);
					try {
						scanEntry(classPathEntry);
					} finally {
						classPathEntry.closeInputStream();
					}
				}
			} catch (RuntimeException rex) {
				if (!ignoreException) {
					ZipUtil.close(zipFile);
					throw rex;
				}
			}
		}
		ZipUtil.close(zipFile);
	}

public static Stream<JarEntry> asStream( final JarInputStream pInputStream ) {
        return StreamSupport.stream(Spliterators.spliteratorUnknownSize(
            new Iterator<JarEntry>() {

                JarEntry entry = null;

                public boolean hasNext() {
                    try {
                        if (entry == null) {
                            entry = pInputStream.getNextJarEntry();
                        }
                        return entry != null;
                    } catch(IOException e) {
                        throw new RuntimeException(e);
                    }
                }

                public JarEntry next() {
                    try {
                        JarEntry result = entry != null
                          ? entry
                          : pInputStream.getNextJarEntry();
                        entry = null;
                        return result;
                    } catch(IOException e) {
                        throw new RuntimeException(e);
                    }
                }

            }, Spliterator.IMMUTABLE), false);
    }

public void return_sync(final String name,
                            final String pattern,
                            byte[] response_info,
                            byte[] response,
                            Integer timeout,
                            final byte[] trans_id,
                            final OtpErlangPid pid)
        throws ReturnSyncException
    {
        try
        {
            OtpOutputStream return_sync = new OtpOutputStream();
            return_sync.write(OtpExternal.versionTag);
            final OtpErlangObject[] tuple = {new OtpErlangAtom("return_sync"),
                                             new OtpErlangString(name),
                                             new OtpErlangString(pattern),
                                             new OtpErlangBinary(response_info),
                                             new OtpErlangBinary(response),
                                             new OtpErlangUInt(timeout),
                                             new OtpErlangBinary(trans_id),
                                             pid};
            return_sync.write_any(new OtpErlangTuple(tuple));
            send(return_sync);
        }
        catch (OtpErlangRangeException e)
        {
            e.printStackTrace(API.err);
            return;
        }
        throw new ReturnSyncException();
    }

